//! Golden tests against corpora captured from the reference JS server.
//!
//! The corpora in tests/golden/protocol are generated by
//! node oracle/golden-protocol.js from the read-only reference repository. They
//! are the executable definition of protocol v2 wire compatibility.

use std::path::{Path, PathBuf};

use poker_protocol::*;
use serde::Deserialize;
use serde_json::Value;

fn corpus_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/golden/protocol")
}

fn read_jsonl<T: for<'de> Deserialize<'de>>(name: &str) -> Vec<T> {
    let path = corpus_dir().join(name);
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));
    text.lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| {
            serde_json::from_str(line)
                .unwrap_or_else(|error| panic!("bad {} line: {error}", path.display()))
        })
        .collect()
}

fn read_json(name: &str) -> Value {
    let path = corpus_dir().join(name);
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|error| panic!("bad {}: {error}", path.display()))
}

#[derive(Debug, Deserialize)]
struct MessageRecord {
    scenario: String,
    context: String,
    message: Value,
}

#[derive(Debug, Deserialize)]
struct ParseErrorRecord {
    label: String,
    raw: String,
    expected: Value,
    actual: Value,
}

#[derive(Debug, Deserialize)]
struct ConfigCase {
    input: Value,
    #[serde(rename = "fallbackAiDelay")]
    fallback_ai_delay: f64,
    output: Value,
}

#[derive(Debug, Deserialize)]
struct NameCase {
    input: Value,
    output: String,
}

#[derive(Debug, Deserialize)]
struct ProbeCase {
    hello: Value,
    expected: bool,
}

#[derive(Debug, Deserialize)]
struct CloseEvent {
    scenario: String,
    kind: String,
    context: String,
    #[serde(default)]
    code: Option<u16>,
    #[serde(default)]
    reason: Option<String>,
    #[serde(rename = "statusCode", default)]
    status_code: Option<u16>,
}

#[derive(Debug, Deserialize)]
struct ReconnectDelay {
    attempt: u32,
    #[serde(rename = "delayMs")]
    delay_ms: u64,
}

/// Every captured server message must parse into a DTO and serialise back to the
/// exact same JSON object (field set, types, nulls and values).
#[test]
fn s2c_messages_roundtrip_field_exact() {
    let records: Vec<MessageRecord> = read_jsonl("s2c-messages.jsonl");
    assert!(
        records.len() >= 100,
        "s2c corpus unexpectedly small: {}",
        records.len()
    );
    let mut types = std::collections::BTreeSet::new();
    for record in &records {
        let parsed = parse_server_message_value(record.message.clone()).unwrap_or_else(|error| {
            panic!(
                "{} / {}: parse failed: {error}",
                record.scenario, record.context
            )
        });
        let serialised = parsed.to_json_value();
        assert_eq!(
            serialised, record.message,
            "{} / {}: wire roundtrip differs",
            record.scenario, record.context
        );
        assert_eq!(
            serialised.get("protocolVersion").and_then(Value::as_u64),
            Some(u64::from(PROTOCOL_VERSION)),
            "{} / {}: protocolVersion envelope missing",
            record.scenario,
            record.context
        );
        types.insert(serialised["type"].as_str().unwrap_or_default().to_owned());
    }
    let expected: std::collections::BTreeSet<String> = SERVER_MESSAGE_TYPES
        .iter()
        .map(|name| (*name).to_owned())
        .collect();
    assert_eq!(
        types, expected,
        "corpus does not cover every server message type"
    );
}

