/// Raw hostile payloads must produce exactly the error reply the reference
/// server sends (code, message and echoed requestId).
#[test]
fn parse_errors_match_reference_replies() {
    let records: Vec<ParseErrorRecord> = read_jsonl("parse-errors.jsonl");
    assert!(records.len() >= 10, "parse-error corpus unexpectedly small");
    for record in &records {
        let kind = record.expected["kind"].as_str().unwrap_or_default();
        match kind {
            "error" => assert_expected_error_reply(record),
            "parsed" => {
                parse_client_message(&record.raw).unwrap_or_else(|error| {
                    panic!("{}: expected a valid message, got {error}", record.label)
                });
            }
            other => panic!("{}: unknown expected kind {other}", record.label),
        }
    }
}

fn assert_expected_error_reply(record: &ParseErrorRecord) {
    let error = match parse_client_message(&record.raw) {
        Ok(message) => panic!(
            "{}: expected a parse error, parsed {:?}",
            record.label,
            message.message_type()
        ),
        Err(error) => error,
    };
    let reply = ServerMessage::Error(error.to_server_error()).to_json_value();
    assert_eq!(
        reply, record.actual,
        "{}: error reply differs from the reference server",
        record.label
    );
    assert_eq!(
        reply["protocolVersion"].as_u64(),
        Some(u64::from(PROTOCOL_VERSION)),
        "{}: protocolVersion envelope missing",
        record.label
    );
}

/// Room config whitelisting must reproduce sanitizeConfig() exactly.
#[test]
fn config_whitelist_matches_reference() {
    let cases: Vec<ConfigCase> = read_jsonl("config-cases.jsonl");
    assert!(cases.len() >= 30, "config corpus unexpectedly small");
    for case in &cases {
        let options: RoomOptionsInput = serde_json::from_value(case.input.clone())
            .unwrap_or_else(|error| panic!("cannot parse config input {:?}: {error}", case.input));
        let config = options.sanitize(case.fallback_ai_delay);
        let actual = serde_json::to_value(&config).expect("room config serialisation");
        assert_eq!(
            actual, case.output,
            "config mismatch for input {:?} (fallback {})",
            case.input, case.fallback_ai_delay
        );
    }
}

/// Player-name normalisation (NFKC, control stripping, trim, truncation) must
/// reproduce normalizeName() exactly, including non-string JSON inputs.
#[test]
fn name_normalisation_matches_reference() {
    let cases: Vec<NameCase> = read_jsonl("name-cases.jsonl");
    assert!(cases.len() >= 20, "name corpus unexpectedly small");
    for case in &cases {
        let actual = normalize_name_value(Some(&case.input));
        assert_eq!(
            actual, case.output,
            "name mismatch for input {:?}",
            case.input
        );
    }
}

/// The desktop service probe predicate must accept/reject exactly like main.js.
#[test]
fn hello_desktop_probe_matrix() {
    let cases: Vec<ProbeCase> = read_jsonl("hello-probe-cases.jsonl");
    assert!(cases.len() >= 6);
    let constants = read_json("server-constants.json");
    let expected_app_version = constants["appVersion"].as_str().expect("appVersion");
    for case in &cases {
        let probe_ok = match parse_server_message_value(case.hello.clone()) {
            Ok(ServerMessage::Hello(hello)) => {
                hello.is_desktop_probe_compatible(expected_app_version)
            }
            Ok(other) => panic!(
                "probe case parsed as {} instead of hello",
                other.message_type()
            ),
            Err(_) => false,
        };
        assert_eq!(
            probe_ok, case.expected,
            "probe mismatch for hello {:?}",
            case.hello
        );
    }
}

/// Constants pinned from the reference server source / instance defaults.
#[test]
fn server_constants_match_golden() {
    let constants = read_json("server-constants.json");
    let number = |key: &str| {
        constants[key]
            .as_u64()
            .unwrap_or_else(|| panic!("server-constants.json missing numeric {key}"))
    };
    assert_eq!(number("protocolVersion"), u64::from(PROTOCOL_VERSION));
    assert_eq!(constants["serverId"], SERVER_ID);
    assert_eq!(constants["serverName"], SERVER_NAME);
    assert_eq!(constants["appVersion"], COMPAT_APP_VERSION);
    assert_eq!(number("emptyRoomTtlMs"), EMPTY_ROOM_TTL_MS);
    assert_eq!(number("maxNameLength"), MAX_NAME_LENGTH as u64);
    assert_eq!(number("rxMaxPayloadBytes"), MAX_PAYLOAD_BYTES as u64);
    assert_eq!(number("heartbeatIntervalMs"), HEARTBEAT_INTERVAL_MS);
    assert_eq!(number("nextHandDelayMs"), NEXT_HAND_DELAY_MS);
    assert_eq!(
        constants["roomCodes"],
        serde_json::to_value(ROOM_CODES).unwrap()
    );
    assert_eq!(
        constants["stackLevels"],
        serde_json::to_value(STACK_LEVELS).unwrap()
    );
    assert_eq!(
        constants["blindLevels"],
        serde_json::to_value(BLIND_LEVELS).unwrap()
    );
    assert_eq!(
        constants["aiDelayLevels"],
        serde_json::to_value(AI_DELAY_LEVELS).unwrap()
    );

    let defaults = &constants["defaults"];
    assert_eq!(
        defaults["aiDelay"].as_u64(),
        Some(u64::from(SERVER_AI_DELAY_DEFAULT_MS))
    );
    assert_eq!(
        defaults["disconnectGraceMs"].as_u64(),
        Some(u64::from(DISCONNECT_GRACE_DEFAULT_MS))
    );
    assert_eq!(
        defaults["maxRooms"].as_u64(),
        Some(u64::from(MAX_ROOMS_DEFAULT))
    );
    assert_eq!(
        defaults["maxConnections"].as_u64(),
        Some(u64::from(MAX_CONNECTIONS_DEFAULT))
    );
    assert_eq!(
        defaults["maxConnectionsPerIp"].as_u64(),
        Some(u64::from(MAX_CONNECTIONS_PER_IP_DEFAULT))
    );
    assert_eq!(
        defaults["rateWindowMs"].as_u64(),
        Some(u64::from(RATE_WINDOW_DEFAULT_MS))
    );
    assert_eq!(
        defaults["maxMessagesPerWindow"].as_u64(),
        Some(u64::from(MAX_MESSAGES_PER_WINDOW_DEFAULT))
    );
    assert_eq!(defaults["trustProxy"].as_bool(), Some(false));
    assert_eq!(defaults["allowedOrigins"], serde_json::json!([]));
}

/// Server-initiated close codes / reasons and the origin rejection status.
#[test]
fn close_events_match_constants() {
    let events: Vec<CloseEvent> = read_jsonl("close-events.jsonl");
    assert_eq!(events.len(), 5, "unexpected close-event corpus size");
    for event in &events {
        assert!(!event.scenario.is_empty());
        match (event.kind.as_str(), event.context.as_str()) {
            ("ws-close", "resume-session-elsewhere") => {
                assert_eq!(event.code, Some(CLOSE_SESSION_REPLACED));
                assert_eq!(event.reason.as_deref(), Some(CLOSE_REASON_SESSION_REPLACED));
            }
            ("ws-close", "message-rate-exceeded") => {
                assert_eq!(event.code, Some(CLOSE_POLICY_VIOLATION));
                assert_eq!(event.reason.as_deref(), Some(CLOSE_REASON_RATE_LIMIT));
            }
            ("ws-close", "server-capacity-reached") => {
                assert_eq!(event.code, Some(CLOSE_TRY_AGAIN_LATER));
                assert_eq!(event.reason.as_deref(), Some(CLOSE_REASON_CAPACITY));
            }
            ("ws-close", "message-too-large") => {
                // The ws layer enforces maxPayload before the application check,
                // so the captured reason is empty; the code is what clients see.
                assert_eq!(event.code, Some(CLOSE_MESSAGE_TOO_BIG));
            }
            ("http-upgrade", "disallowed-origin") => {
                assert_eq!(event.status_code, Some(ORIGIN_REJECTED_HTTP_STATUS));
            }
            other => panic!("unexpected close event {other:?}"),
        }
    }
}

/// Browser-client reconnect behaviour that a Rust client must mirror.
#[test]
fn client_behaviour_matches_constants() {
    let behaviour = read_json("client-behaviour.json");
    let terminal: Vec<u16> = behaviour["terminalCloseCodes"]
        .as_array()
        .expect("terminalCloseCodes")
        .iter()
        .map(|value| value.as_u64().expect("close code") as u16)
        .collect();
    assert_eq!(terminal, TERMINAL_CLOSE_CODES.to_vec());
    for code in [1006u16, 1011, 1005, 1001] {
        assert!(
            !is_terminal_close_code(code),
            "close code {code} must not be terminal"
        );
    }
    assert_eq!(behaviour["sessionStorageKey"], SESSION_STORAGE_KEY);
    let prefixes: Vec<String> = behaviour["requestIdPrefixes"]
        .as_array()
        .expect("requestIdPrefixes")
        .iter()
        .map(|value| value.as_str().expect("prefix").to_owned())
        .collect();
    assert_eq!(prefixes, REQUEST_ID_PREFIXES.map(str::to_owned).to_vec());
    assert_eq!(
        behaviour["reconnectDelayCapMs"].as_u64(),
        Some(RECONNECT_MAX_DELAY_MS)
    );
    assert_eq!(
        behaviour["reconnectBaseDelayMs"].as_u64(),
        Some(RECONNECT_BASE_DELAY_MS)
    );
    assert_eq!(
        behaviour["reconnectMaxDoublings"].as_u64(),
        Some(u64::from(RECONNECT_MAX_DOUBLINGS))
    );
    assert_eq!(
        behaviour["reconnectJitterMs"].as_u64(),
        Some(RECONNECT_JITTER_MS)
    );
    let delays: Vec<ReconnectDelay> =
        serde_json::from_value(behaviour["reconnectDelaysMs"].clone()).expect("reconnectDelaysMs");
    assert!(delays.len() >= 6);
    for delay in &delays {
        assert_eq!(
            reconnect_delay_ms(delay.attempt, 0.5),
            delay.delay_ms,
            "reconnect delay mismatch for attempt {}",
            delay.attempt
        );
    }
}
